reproduction.helper_declarations:
input StatusOnlyPatch { status: Todo.status optional }
type DuePatch = Object { due_at: Todo.due_at optional }
function provide_patch(value: DuePatch) fails EmptyPatch -> DuePatch { if false { reject EmptyPatch } return value }
function keep_patch(todo: Todo, value: DuePatch) -> DuePatch { return value }

reproduction.inserted_owned_action:
action extra(todo_id: Todo.id, changes: StatusOnlyPatch, incoming: DuePatch) fails TodoNotFound, EmptyPatch, TodoMutationConflict -> Unit {
 var result = match provide_patch(incoming) {
  success(changes) => keep_patch(attempt update required Todo { where: id == todo_id patch: changes empty: EmptyPatch missing: TodoNotFound { todo_id: todo_id } conflict: TodoMutationConflict }, changes)
  failure EmptyPatch => propagate
 }
}
